//! `GET /`: the web UI, one page built into the firmware. It routes with the
//! URL fragment, so there are no other paths.

use picoserve::ResponseSent;
use picoserve::io::{Read, Write};
use picoserve::request::Request;
use picoserve::response::{Content, Response, ResponseWriter, StatusCode};
use picoserve::routing::MethodHandlerService;

use super::AppState;

mod bundle {
    //! The page and the values derived from it, generated by `build.rs`.
    include!(concat!(env!("OUT_DIR"), "/web_ui.rs"));
}

const CONTENT_TYPE: &str = "text/html; charset=utf-8";

/// Headers on every answer with the page, including `304`.
const HEADERS: &[(&str, &str)] = &[
    ("ETag", bundle::ETAG),
    ("Cache-Control", "no-cache"),
    ("Content-Security-Policy", bundle::CONTENT_SECURITY_POLICY),
    ("X-Content-Type-Options", "nosniff"),
    ("Referrer-Policy", "no-referrer"),
    ("X-Frame-Options", "DENY"),
    ("Cross-Origin-Opener-Policy", "same-origin"),
    ("Cross-Origin-Resource-Policy", "same-origin"),
    (
        "Permissions-Policy",
        "camera=(), microphone=(), geolocation=(), usb=(), serial=()",
    ),
];

/// Serves the page to `GET` and `HEAD`.
pub(super) struct Ui;

impl MethodHandlerService<AppState> for Ui {
    async fn call_method_handler_service<R: Read, W: ResponseWriter<Error = R::Error>>(
        &self,
        _state: &AppState,
        _path_parameters: (),
        method: &str,
        request: Request<'_, R>,
        writer: W,
    ) -> Result<ResponseSent, W::Error> {
        let head = match method {
            "GET" => false,
            "HEAD" => true,
            _ => {
                let connection = request.body_connection.finalize().await?;
                let response = Response::empty(StatusCode::METHOD_NOT_ALLOWED)
                    .with_header("Allow", "GET, HEAD");
                return writer.write_response(connection, response).await;
            }
        };

        let fresh = request
            .parts
            .headers()
            .get("If-None-Match")
            .and_then(|value| value.as_str().ok())
            .is_some_and(|value| etag_listed(value, bundle::ETAG));
        let connection = request.body_connection.finalize().await?;

        if fresh {
            let response = Response::empty(StatusCode::NOT_MODIFIED).with_headers(HEADERS);
            return writer.write_response(connection, response).await;
        }
        let response = Response::new(StatusCode::OK, Page { head })
            .with_headers(HEADERS)
            .with_headers(bundle::GZIP.then_some(("Content-Encoding", "gzip")));
        writer.write_response(connection, response).await
    }
}

/// The page. For `HEAD` it reports the length of the body it doesn't write.
struct Page {
    head: bool,
}

impl Content for Page {
    fn content_type(&self) -> &'static str {
        CONTENT_TYPE
    }

    fn content_length(&self) -> usize {
        bundle::PAGE.len()
    }

    async fn write_content<W: Write>(self, mut writer: W) -> Result<(), W::Error> {
        if self.head {
            return Ok(());
        }
        writer.write_all(bundle::PAGE).await
    }
}

/// Whether the `If-None-Match` header `value` lists `etag`, or any tag.
/// Weak and strong tags compare equal, as that header's comparison does.
fn etag_listed(value: &str, etag: &str) -> bool {
    value
        .split(',')
        .map(str::trim)
        .any(|listed| listed == "*" || listed.strip_prefix("W/").unwrap_or(listed) == etag)
}
